// ─── File: src/main/java/com/bank/dispatch/service/FeeCalculator.java ───
// OVERLOADING: same name, different parameter lists — compile-time resolution
package com.bank.dispatch.service;

import java.math.BigDecimal;
import java.math.RoundingMode;

public class FeeCalculator {

    // OVERLOAD 1: just amount
    public BigDecimal calculateFee(BigDecimal amount) {
        return amount.multiply(new BigDecimal("0.001")).setScale(2, RoundingMode.HALF_UP);
    }

    // OVERLOAD 2: amount + fee type
    public BigDecimal calculateFee(BigDecimal amount, String feeType) {
        return switch (feeType) {
            case "BROKERAGE" -> calculateFee(amount);
            case "GST" -> calculateFee(amount).multiply(new BigDecimal("0.18")).setScale(2, RoundingMode.HALF_UP);
            case "STT" -> amount.multiply(new BigDecimal("0.00025")).setScale(2, RoundingMode.HALF_UP);
            default -> BigDecimal.ZERO;
        };
    }

    // OVERLOAD 3: amount + fee type + intraday flag
    public BigDecimal calculateFee(BigDecimal amount, String feeType, boolean isIntraday) {
        BigDecimal base = calculateFee(amount, feeType);
        return isIntraday ? base.multiply(new BigDecimal("0.5")).setScale(2, RoundingMode.HALF_UP) : base;
    }

    // (Avoid) THIS WOULD NOT COMPILE — return type alone is NOT a valid overload:
    // public String calculateFee(BigDecimal amount) { return "fee"; }
}
```

