// OVERRIDING: same method name + same params, DIFFERENT behavior
package com.bank.dispatch.model;

import java.math.BigDecimal;
import java.math.RoundingMode;

public class SavingsAccount extends Account {
    private final BigDecimal annualRate;

    public SavingsAccount(String accountId, BigDecimal balance, BigDecimal annualRate) {
        super(accountId, balance);
        this.annualRate = annualRate;
    }

    @Override  // MUST use @Override — compile-time check for correct signature
    public BigDecimal calculateInterest() {
        // DIFFERENT behavior: balance × rate / 12
        return getBalance().multiply(annualRate)
            .divide(BigDecimal.valueOf(12), 2, RoundingMode.HALF_UP);
    }

    @Override
    public String getTypeLabel() {
        return "SAVINGS (" + annualRate.multiply(BigDecimal.valueOf(100)) + "%)";
    }
}
