// ─── File: src/test/java/com/bank/dispatch/OverloadingTest.java ───
// PROOF: overloading is resolved at COMPILE TIME
package com.bank.dispatch;

import com.bank.dispatch.service.FeeCalculator;
import org.junit.jupiter.api.Test;
import java.math.BigDecimal;
import static org.assertj.core.api.Assertions.*;

class OverloadingTest {

    FeeCalculator calc = new FeeCalculator();

    @Test
    void overload1_justAmount() {
        BigDecimal fee = calc.calculateFee(new BigDecimal("100000"));
        assertThat(fee).isEqualByComparingTo("100");  // 0.1% of 100K
        // Compiler saw: calculateFee(BigDecimal) → picked OVERLOAD 1
    }

    @Test
    void overload2_amountPlusFeeType() {
        BigDecimal gst = calc.calculateFee(new BigDecimal("100000"), "GST");
        assertThat(gst).isEqualByComparingTo("18");  // brokerage 100 × 18% = 18
        // Compiler saw: calculateFee(BigDecimal, String) → picked OVERLOAD 2
    }

    @Test
    void overload3_amountPlusFeeTypePlusIntraday() {
        BigDecimal intradayFee = calc.calculateFee(new BigDecimal("100000"), "BROKERAGE", true);
        assertThat(intradayFee).isEqualByComparingTo("50");  // 100 × 50% intraday discount
        // Compiler saw: calculateFee(BigDecimal, String, boolean) → picked OVERLOAD 3
    }

    @Test
    void compileTimeProof_sameObjectDifferentArgs() {
        // SAME FeeCalculator object. DIFFERENT arguments → DIFFERENT methods called.
        FeeCalculator sameCalc = new FeeCalculator();
        BigDecimal r1 = sameCalc.calculateFee(new BigDecimal("100000"));
        BigDecimal r2 = sameCalc.calculateFee(new BigDecimal("100000"), "BROKERAGE");
        BigDecimal r3 = sameCalc.calculateFee(new BigDecimal("100000"), "BROKERAGE", true);

        assertThat(r1).isEqualByComparingTo("100");
        assertThat(r2).isEqualByComparingTo("100");
        assertThat(r3).isEqualByComparingTo("50");
        // Same object, different arguments → compiler picked different methods
        // This proves: overloading is resolved at COMPILE TIME based on ARGUMENT TYPES.
    }
}
```

```java
// ─── File: src/test/java/com/bank/dispatch/OverridingTest.java ───
// PROOF: overriding is resolved at RUNTIME
package com.bank.dispatch;

import com.bank.dispatch.model.*;
import org.junit.jupiter.api.Test;
import java.math.BigDecimal;
import java.util.List;
import static org.assertj.core.api.Assertions.*;

class OverridingTest {

    @Test
    void runtimeProof_sameCallDifferentBehavior() {
        // Variable type: Account. Actual type: SavingsAccount / CurrentAccount.
        Account savings = new SavingsAccount("SAV001", new BigDecimal("120000"), new BigDecimal("0.04"));
        Account current = new CurrentAccount("CUR001", new BigDecimal("500000"));

        // SAME method call on SAME variable type (Account):
        BigDecimal savingsInterest = savings.calculateInterest();
        BigDecimal currentInterest = current.calculateInterest();

        // DIFFERENT results — JVM dispatched to DIFFERENT methods at RUNTIME:
        assertThat(savingsInterest).isEqualByComparingTo("400");  // 120000 × 4% / 12
        assertThat(currentInterest).isEqualByComparingTo("0");    // zero for current

        // PROOF: the COMPILER didn't decide this. The JVM did.
        // The compiler saw: Account.calculateInterest() for BOTH calls.
        // At runtime: JVM checked actual type → dispatched to correct override.
    }

    @Test
    void runtimeProof_polymorphicLoop() {
        List<Account> accounts = List.of(
            new SavingsAccount("SAV001", new BigDecimal("120000"), new BigDecimal("0.04")),
            new CurrentAccount("CUR001", new BigDecimal("500000")),
            new SavingsAccount("SAV002", new BigDecimal("60000"), new BigDecimal("0.035"))
        );

        // ONE loop. SAME call. DIFFERENT results.
        BigDecimal totalInterest = accounts.stream()
            .map(Account::calculateInterest)  // runtime dispatch per element!
            .reduce(BigDecimal.ZERO, BigDecimal::add);

        // 400 + 0 + 175 = 575
        assertThat(totalInterest).isEqualByComparingTo("575");
    }

    @Test
    void runtimeProof_objectReferenceDispatch() {
        // ULTIMATE proof: call through Object reference
        Object ref = new SavingsAccount("SAV001", new BigDecimal("120000"), new BigDecimal("0.04"));

        // ref.calculateInterest();  // WON'T COMPILE — Object doesn't have calculateInterest()
        // BUT toString() IS on Object — and SavingsAccount inherits from Account which inherits from Object

        String str = ref.toString();
        // If SavingsAccount overrides toString(): JVM calls SavingsAccount.toString() at RUNTIME
        // If not: JVM calls Object.toString() → "SavingsAccount@1a2b3c"
        // This proves: JVM dispatches based on ACTUAL type, not variable type.
        assertThat(str).isNotNull();
    }

    @Test
    void overrideAnnotationCatchesMistakes() {
        // @Override makes the compiler verify the method ACTUALLY overrides something.
        // Without @Override: a typo in the method name creates a NEW method, not an override!
        // Example: calculateIntrest() instead of calculateInterest() — no error without @Override!
        // With @Override: compiler says "calculateIntrest() does not override anything" → caught!
        assertThat(true).isTrue();
    }

    @Test
    void getTypeLabelOverriddenPerType() {
        Account savings = new SavingsAccount("SAV001", BigDecimal.ZERO, new BigDecimal("0.04"));
        Account current = new CurrentAccount("CUR001", BigDecimal.ZERO);

        assertThat(savings.getTypeLabel()).contains("SAVINGS").contains("4");
        assertThat(current.getTypeLabel()).contains("CURRENT").contains("zero");
        // Same call, different results — runtime polymorphism!
    }

    // ═══ SUMMARY: THE KEY DIFFERENCE ═══
    @Test
    void summary_overloadingVsOverriding() {
        // OVERLOADING: same object, different ARGUMENTS → compiler picks method
        // OVERRIDING: different objects, same CALL → JVM picks method at runtime

        // Overloading = COMPILE-TIME polymorphism (static dispatch)
        // Overriding = RUNTIME polymorphism (dynamic dispatch / virtual method invocation)
        assertThat(true).isTrue();
    }
}
